export const muscleById = Object.fromEntries(MUSCLES.map(m => [m.id, m]));
export const exerciseById = Object.fromEntries(EXERCISES.map(e => [e.id, e]));
// which exercises train each muscle (primary first)
export function exercisesFor(muscleId) {
  const p = EXERCISES.filter(e => e.primary.includes(muscleId)), s = EXERCISES.filter(e => !e.primary.includes(muscleId) && e.secondary.includes(muscleId));
  return { primary: p, secondary: s };
}
// muscles that often work alongside this one
export function relatedMuscles(muscleId) {
  const count = {};
  for (const e of EXERCISES) {
    const all = [...e.primary, ...e.secondary];
    if (!all.includes(muscleId)) continue;
    for (const m of all) if (m !== muscleId) count[m] = (count[m] || 0) + 1;
  }
  return Object.entries(count).sort((a, b) => b[1] - a[1]).slice(0, 6).map(([m]) => m);
}
